import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: '신규' 게시글은 최근 7일 안에 등록된 공지·게시글로 본다.
const NEW_POST_DAYS = 7;

@Controller('api/v1')
export class FnSfr04002Controller {
  @Get('/menu-new-counts')
  async getMenuNewCounts(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    try {
      return await transaction(async (db) => {
        // 메일: 현재 사용자가 받은 MAIL 중 아직 읽지 않은 건수
        const mailRows = await db.query(
          `SELECT COUNT(*) AS "cnt"
             FROM message_recipient mr
             JOIN message m ON m.message_id = mr.message_id
            WHERE mr.recipient_id = CAST(:userId AS bigint)
              AND mr.read_at IS NULL
              AND m.message_type = 'MAIL'`,
          { userId: user.id },
        );
        // 가정: 전자결재 신규 건수는 본인이 기안한 문서 중 결재대기 상태인 건수로 본다 (결재선 테이블이 없어 본인 범위로 한정).
        const approvalRows = await db.query(
          `SELECT COUNT(*) AS "cnt"
             FROM approval_document d
            WHERE d.drafter_id = CAST(:userId AS bigint)
              AND d.approval_status = '결재대기'`,
          { userId: user.id },
        );
        // 가정: 게시판 신규 건수는 최근 NEW_POST_DAYS일 안에 등록되고 공개범위(전체/부서/개인)에 해당하는 공지·게시글 건수
        const boardRows = await db.query(
          `SELECT COUNT(*) AS "cnt"
             FROM post p
             JOIN employee au ON au.employee_id = p.author_id
             JOIN employee me ON me.employee_id = CAST(:userId AS bigint)
            WHERE p.created_at >= now() - CAST(:days AS integer) * interval '1 day'
              AND (
                p.visibility_scope = 'ALL'
                OR (p.visibility_scope = 'DEPARTMENT' AND au.department_id = me.department_id)
                OR (p.visibility_scope = 'INDIVIDUAL' AND p.author_id = me.employee_id)
              )`,
          { userId: user.id, days: NEW_POST_DAYS },
        );
        return {
          mailNewCount: Number(mailRows[0]?.cnt ?? 0),
          approvalNewCount: Number(approvalRows[0]?.cnt ?? 0),
          boardNewCount: Number(boardRows[0]?.cnt ?? 0),
        };
      });
    } catch (e) {
      if (e instanceof ApiError) {
        throw e;
      }
      throw new ApiError(502, 'NEW_COUNT_AGGREGATION_FAILED', '신규 건수를 집계하지 못했습니다.');
    }
  }
}

