import { useData, call, Tiles, Band, ErrorText, Num } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr04002Page({ role, notify }: PageProps) {
  const { data, error, loading, reload } = useData<Row>(
    () => call<Row>('GET', '/menu-new-counts', role),
    [role],
  );

  const menus: [string, unknown][] = data
    ? [
        ['메일', data.mailNewCount],
        ['전자결재', data.approvalNewCount],
        ['게시판', data.boardNewCount],
      ]
    : [];
  // 건수가 있는 메뉴에만 신규 건수를 표시한다.
  const items: [string, JSX.Element][] = menus
    .filter(([, count]) => Number(count) > 0)
    .map(([label, count]) => [label, <Num value={count} />]);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>메뉴별 신규 건수</h2>
        <Band>
          <button
            type="button"
            onClick={() => {
              reload();
              notify('신규 건수를 다시 읽었습니다.');
            }}
          >
            새로고침
          </button>
        </Band>
        {loading && <p>불러오는 중입니다.</p>}
        {error && <ErrorText text={error} />}
        {!loading && !error && items.length > 0 && <Tiles items={items} />}
        {!loading && !error && items.length === 0 && <p>새로 들어온 건이 없습니다.</p>}
      </section>
    </div>
  );
}
